mapper.select:
SELECT COALESCE(SUM(id.qty), 0)
FROM inbound_detail id
JOIN inbound i ON i.inbound_id = id.inbound_id
WHERE i.account_id = #{accountId}
AND id.foreign_product_id = #{foreignProductId}

mapper.update:
UPDATE inbound_detail
SET current_qty = current_qty - #{qty}
WHERE inbound_detail_id = #{inboundDetailId} AND current_qty >= #{qty}

mapper.select:
SELECT id.inbound_id AS inboundId, id.inbound_detail_id AS inboundDetailId, id.source_broker AS sourceBroker, id.qty AS qty, id.current_qty AS currentQty, id.recorded_at AS recordedAt, id.purchase_date AS purchaseDate, id.purchase_price AS purchasePrice, id.purchase_currency AS purchaseCurrency, id.purchase_fx_rate AS purchaseFxRate FROM inbound_detail id WHERE id.inbound_id IN
#{inboundId}
ORDER BY id.inbound_id, id.purchase_date ASC
